 {id:'ermes-costello',name:'Ermes Costello',part:6,role:'Jolyne’nin müttefiki · Stone Ocean',intro:'Green Dolphin Street Hapishanesi’nde Jolyne’yle arkadaş olan mahkûm.',birth:'Kaynaklarda belirtilmemiş',height:'Kaynaklarda belirtilmemiş',personality:'Gözü pek, kararlı ve ailesine bağlı',ability:'Stand kullanıcısı',stand:{name:'Kiss',type:'Yakın menzilli Stand',description:'Nesnelerin üzerine çıkartma yerleştirir; çıkartma kaldırıldığında kopyalar yeniden birleşirken çarpışma etkisi yaratır.',facts:{'Yetenek':'Çıkartmayla nesne kopyalama ve birleştirme','Kullanıcı':'Ermes Costello'}},events:['Jolyne’yle hapishanede tanışır ve ona yardım eder.','Kız kardeşi Gloria’nın intikamını almak için hapishaneye girmiştir.','Pucci’ye karşı Jolyne ve diğer mahkûmlarla birlikte savaşır.'],image:null,source:'Manga/anime: Stone Ocean (Part 6).'},
 {id:'foo-fighters',name:'Foo Fighters',part:6,role:'Jolyne’nin müttefiki · Stone Ocean',intro:'Plankton kolonisi ve bir Stand’in birleşmesiyle oluşan bilinçli varlık.',birth:'Bilinmiyor',height:'Kaynaklarda belirtilmemiş',personality:'Meraklı, sadık ve insan olmayı öğrenen',ability:'Plankton kolonisi; Stand kullanıcısı',stand:{name:'Foo Fighters',type:'Plankton temelli Stand',description:'Plankton kolonisini kontrol ederek beden oluşturur; suya ve neme ihtiyaç duyar, yaralarını planktonla onarabilir.',facts:{'Yetenek':'Plankton bedenini kontrol etme ve yenileme','Kullanıcı':'Foo Fighters'}},events:['Pucci’nin koruduğu Stand diskinden doğar.','Jolyne’yle karşılaştıktan sonra onun müttefiki olur.','Nihai çatışmalarda Emporio’yu koruyarak hayatını kaybeder.'],image:null,source:'Manga/anime: Stone Ocean (Part 6).'},
 {id:'weather-report',name:'Weather Report',part:6,role:'Jolyne’nin müttefiki · Stone Ocean',intro:'Green Dolphin Street Hapishanesi’nde hafızasını kaybetmiş olarak yaşayan mahkûm.',birth:'Kaynaklarda belirtilmemiş',height:'Kaynaklarda belirtilmemiş',personality:'Sessiz, içine kapanık ve koruyucu',ability:'Stand kullanıcısı',stand:{name:'Weather Report',type:'Hava kontrolü Stand’i',description:'Havayı ve atmosfer olaylarını kontrol edebilir. Belleğine bağlı gizli yeteneği Heavy Weather, optik yanılsamalar oluşturur.',facts:{'Yetenek':'Hava olaylarını kontrol etme; Heavy Weather','Kullanıcı':'Weather Report'}},events:['Jolyne’nin Pucci’nin planına karşı mücadelesine katılır.','Geçmişini ve Pucci’yle olan aile bağını yeniden keşfeder.','Stand diskini Emporio’ya ulaştırdıktan sonra hayatını kaybeder.'],image:null,source:'Manga/anime: Stone Ocean (Part 6).'},
 {id:'narciso-anasui',name:'Narciso Anasui',part:6,role:'Jolyne’nin müttefiki · Stone Ocean',intro:'Jolyne’ye yardım ederek onunla birlikte hapishaneden kaçmayı amaçlayan mahkûm.',birth:'Kaynaklarda belirtilmemiş',height:'Kaynaklarda belirtilmemiş',personality:'Yoğun, kararlı ve Jolyne’ye bağlı',ability:'Stand kullanıcısı',stand:{name:'Diver Down',type:'Yakın menzilli Stand',description:'Nesnelerin ve canlıların içine dalıp yapısını içeriden değiştirebilir; depoladığı darbeyi farklı bir noktada açığa çıkarabilir.',facts:{'Yetenek':'Yapılara girme ve içlerini yeniden düzenleme','Kullanıcı':'Narciso Anasui'}},events:['Jolyne’yle hapishanede ittifak kurar.','Pucci’nin planını durdurmak için onunla birlikte savaşır.','Jolyne’yi korurken son çatışmada hayatını kaybeder.'],image:null,source:'Manga/anime: Stone Ocean (Part 6).'},
 {id:'emporio-alnino',name:'Emporio Alnino',part:6,role:'Jolyne’nin müttefiki · Stone Ocean',intro:'Hapishane içinde saklanan, Pucci’nin planı ve hayalet odaları hakkında bilgi sahibi çocuk.',birth:'Kaynaklarda belirtilmemiş',height:'Kaynaklarda belirtilmemiş',personality:'Dikkatli, zeki ve cesur',ability:'Stand kullanıcısı',stand:{name:'Burning Down the House',type:'Hayalet oda Stand’i',description:'Artık var olmayan nesnelerin hayalet biçimlerine ve hapishanedeki gizli hayalet odaya erişmesini sağlar.',facts:{'Yetenek':'Hayalet oda ve nesnelere erişim','Kullanıcı':'Emporio Alnino'}},events:['Jolyne’ye hapishanede yol gösterir ve müttefiklerini tanıtır.','Weather Report’un Stand diskini alarak Pucci’ye karşı kullanır.','Evrenin değişiminin ardından hayatta kalan tek eski ekip üyesi olur.'],image:null,source:'Manga/anime: Stone Ocean (Part 6).'}
